def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def normalize_phone(value):
        value = value or ""
        marker = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        return digits

    def valid_phone(value):
        return len(value) == 10 and value[0] not in {"0", "1"}

    def normalize_zip(value):
        value = (value or "").strip()
        if "-" in value:
            value = value.split("-", 1)[0]

        if len(value) == 4 and value.isdigit():
            value = "0" + value

        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError("Unsupported updated value: {!r}".format(value))

    def is_opted_out(value):
        return (value or "").strip().lower() in {
            "y", "yes", "true", "1"
        }

    normalized_rows = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        email_is_valid = valid_email(email)
        phone_is_valid = valid_phone(phone)

        # Drop rows that have neither a valid email nor a valid phone.
        if not email_is_valid and not phone_is_valid:
            continue

        first_name = normalize_name(row["first_name"])
        last_name = normalize_name(row["last_name"])
        source = (row["source"] or "").strip().lower()

        normalized_rows.append({
            "input_index": input_index,
            "first_name": first_name,
            "last_name": last_name,
            "last_name_key": last_name.casefold(),
            "email": email if email_is_valid else "",
            "phone": phone if phone_is_valid else "",
            "zip": normalize_zip(row["zip"]),
            "source": source,
            "manual": source == "manual",
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"] or "")
                if tag.strip()
            },
        })

    count = len(normalized_rows)
    parent = list(range(count))
    rank = [0] * count

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        if row["phone"] and row["last_name_key"]:
            key = (row["phone"], row["last_name_key"])
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index, row in enumerate(normalized_rows):
        groups.setdefault(find(index), []).append(row)

    def pick_field(group, field):
        candidates = [row for row in group if row[field] != ""]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["manual"],
                row["updated_dt"],
                -row["input_index"],
            ),
        )
        return best[field]

    output = []

    for group in groups.values():
        latest = max(row["updated_dt"] for row in group)
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        output.append({
            "first_name": pick_field(group, "first_name"),
            "last_name": pick_field(group, "last_name"),
            "zip": pick_field(group, "zip"),
            "email": pick_field(group, "email"),
            "phone": pick_field(group, "phone"),
            "source": pick_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest.strftime("%Y-%m-%d"),
            "_earliest_index": min(row["input_index"] for row in group),
        })

    output.sort(key=lambda person: person["_earliest_index"])
    for person in output:
        del person["_earliest_index"]

    return output
